"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["55758"],{86892(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.retificacao.fato_ja_coletado_removido","status":422,"titulo":"A retifica\xe7\xe3o n\xe3o retira da inscri\xe7\xe3o fato que ela j\xe1 coleta"},"descricao":{"codigo":"uniplus.selecao.retificacao.fato_ja_coletado_removido","requisitos":["UNI-REQ-0144","UNI-REQ-0212"],"oQueAconteceu":["**Hoje**, na retifica\xe7\xe3o, a API recusa s\xf3 no formul\xe1rio de inscri\xe7\xe3o: a inscri\xe7\xe3o\\nfoi regravada (`PUT .../formularios/inscricao/itens`) sem um fato que a vers\xe3o\\npublicada dela j\xe1 coleta (retirada), ou com esse fato movido de item para campo de\\ngrupo, ou de um grupo para outro (mudan\xe7a de lugar). A recusa sai com **422**, e o\\n`detail` cita o fato. A API protege o fato porque quem se inscreveu numa vers\xe3o\\nanterior o informou, e os outros formul\xe1rios e as vers\xf5es seguintes contam com ele.","**Previsto** com o UNI-REQ-0212: a **retirada** de pergunta passa a ser aceita em\\nqualquer formul\xe1rio; se a vers\xe3o nova ainda usar o fato retirado, a recusa \xe9\\n`uniplus.selecao.retificacao.fato_ausente_de_versao_publicada`. A recusa por este\\nc\xf3digo fica s\xf3 para a **mudan\xe7a de lugar**, que passa a valer para qualquer\\nformul\xe1rio com envio, como a habilita\xe7\xe3o, com a grava\xe7\xe3o dos itens dele (`PUT\\n.../formularios/{codigo}/itens`). A extens\xe3o a outros formul\xe1rios \xe9 regra prevista,\\nainda n\xe3o emitida pela API."],"comoResolver":["Se a recusa foi pela retirada (hoje, na inscri\xe7\xe3o), volte a incluir o fato no\\nformul\xe1rio, no mesmo lugar em que a vers\xe3o publicada o coleta (como pergunta avulsa\\nou no mesmo grupo), e regrave os itens; se a pergunta n\xe3o deve mais aparecer,\\nmantenha-a nesta retifica\xe7\xe3o e registre a necessidade de retir\xe1-la, porque a retirada\\npassa a ser aceita quando a API aplicar o UNI-REQ-0212. Se a recusa foi pela mudan\xe7a\\nde lugar, mantenha o fato no lugar em que a vers\xe3o publicada o coleta (pergunta\\navulsa ou o mesmo grupo): a mudan\xe7a de lugar continua recusada tamb\xe9m depois disso,\\nem qualquer formul\xe1rio com envio."],"ondeAparece":["Defini\xe7\xe3o dos itens do formul\xe1rio de inscri\xe7\xe3o"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Retificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);